import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
export const oxygenCases=[{equation:'2Mg + O₂ → 2MgO',gain:'Mg',loss:'none',options:['Mg','O₂','MgO','none']},{equation:'CuO + H₂ → Cu + H₂O',gain:'H₂',loss:'CuO',options:['CuO','H₂','Cu','H₂O','none']},{equation:'2CuO + C → 2Cu + CO₂',gain:'C',loss:'CuO',options:['CuO','C','Cu','CO₂','none']}];
export const rankCases=[{evidence:['A displaces B from its compound.','B displaces C from its compound.'],answer:['A','B','C']},{evidence:['Under identical dilute-acid conditions, X reacts rapidly, Y slowly.','Z shows no reaction; all samples are clean and have equal exposed area.'],answer:['X','Y','Z']},{evidence:['P displaces Q and R.','R displaces Q.'],answer:['P','R','Q']}];
export function showChanges(kind,t=null,reveal=false){const oxygen=kind==='oxygen';renderDiagram(oxygen?'Track the oxygen transfer':'Read evidence → infer order',oxygen?t?.equation||'Oxygen gain / oxygen loss':'Most reactive → least reactive',`<div class="inventory-board"><span class="eyebrow">${oxygen?'OXYGEN ACCOUNT':'QUALITATIVE EVIDENCE'}</span>${oxygen?`<div class="inventory-row"><span>${t?.equation||'Metal + oxygen → metal oxide'}</span></div><div class="inventory-row"><span>${reveal?'Gains oxygen: '+t.gain:'Predict which starting substance gains oxygen'}</span></div><div class="inventory-row"><span>${reveal?'Loses oxygen: '+(t.loss==='none'?'none of the listed starting substances':t.loss):'Predict which starting substance loses oxygen'}</span></div>`:(t?.evidence||['Use observations made under comparable conditions.','Successful displacement places the added metal above the displaced metal.']).map(s=>`<div class="inventory-row"><span>${s}</span></div>`).join('')+(reveal?`<p class="inventory-outcome">${t.answer.join(' > ')}</p>`:'')}<p class="diagram-caption">${oxygen?'Atom bookkeeping, not a model of the reaction mechanism.':'Symbolic observations, not instructions for handling metals or acid.'}</p></div>`,oxygen?'GAIN = OXIDATION · LOSS = REDUCTION':'CONTROL CONDITIONS · COMBINE EVIDENCE');}
